using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
using VisionCore;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.Fixture;
static class Program {
 static int count;static void Check(bool yes,string message){if(!yes)throw new Exception(message);Console.WriteLine($"PASS {++count}: {message}");}
 static Dictionary<string,JsonElement> Defaults(FixturePlugin p)=>p.Descriptor.Parameters.ToDictionary(v=>v.Name,v=>v.DefaultValue!.Value.Clone());
 static Dictionary<string,PortValue> Inputs(double x=1,double scale=1)=>new(){["InPointX"]=PortValue.Number(x),["InPointY"]=PortValue.Number(2),["InAngle"]=PortValue.Number(3),["MatchScaleX"]=PortValue.Number(scale),["MatchScaleY"]=PortValue.Number(1)};
 static IEnumerable<DependencyObject> Walk(DependencyObject node){yield return node;for(int i=0;i<VisualTreeHelper.GetChildrenCount(node);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(node,i)))yield return child;}
 static ModuleResult Run(FixturePlugin p,string id,Dictionary<string,JsonElement> values,Dictionary<string,PortValue> inputs,ModuleExecutionScope? scope=null)=>p.CreateRuntime().ExecuteAsync(new(id,Environment.CurrentDirectory,inputs,values){Scope=scope},default).Result;
 static double Number(ModuleResult r,string key)=>r.Outputs[key].As<double>();
 [STAThread]static int Main(){try{var app=new Application();SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(app.Dispatcher));Runtime();SaveFormat();Configuration();Console.WriteLine($"PASS {count} production Fixture checks; original native not executed");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{Application.Current?.Shutdown();}}
 static void Runtime(){var p=new FixturePlugin();var values=Defaults(p);using var scope=new ModuleExecutionScope();var r=Run(p,"a",values,Inputs(),scope);Check(r.Status==ModuleStatus.Success&&r.Outputs["ModuStatus"].As<long>()==1,"normal pose publication");Check(Number(r,"FixtureInitPointX")==1&&Number(r,"FixtureRunPointX")==1,"unlocked reference tracks run");r=Run(p,"a",values,Inputs(9),scope);Check(Number(r,"FixtureInitPointX")==9,"unlocked reference follows next frame");Check(r.Outputs["Position Correction Info"].As<FixtureValue>().Reference.ScaleX==1,"typed source FIXTURE output");
  var first=Run(p,"zero",values,Inputs(0,0),scope);Check(Number(first,"FixtureRunScaleX")==0&&first.Outputs["Position Correction Info"].As<FixtureValue>().Run.ScaleX==0,"source zero scale is transported without inverse math");Check(Run(p,"max",values,Inputs(0,10000),scope).Status==ModuleStatus.Success,"source maximum10000 accepted");foreach(double scale in new[]{-1d,10000.001})Check(Run(p,"bad",values,Inputs(0,scale),scope).NativeErrorCode==0xe000032e,"source scale range rejects "+scale);
  var arrays=Inputs();arrays["InPointX"]=PortValue.NumberArray([12,99]);r=Run(p,"array",values,arrays,scope);Check(Number(r,"FixtureRunPointX")==12,"batch input reads only index0");r=Run(p,"missing",values,[],scope);Check(r.Outputs["ModuStatus"].As<long>()==1&&Number(r,"FixtureRunScaleX")==1&&Number(r,"FixtureRunAngle")==0,"direct native-domain unbound codes use defaults and AND classification");var empty=Inputs();empty["InAngle"]=PortValue.NumberArray([]);Check(Run(p,"empty",values,empty,scope).NativeErrorCode==0xe0000001,"bound empty E314 maps source generic read failure");
  var reader=new Reader();scope.RegisterService<IToolNumericInputReader>(reader,false);reader.Values=Inputs().ToDictionary(v=>v.Key,v=>new ToolNumericInputReadResult(0,0,v.Value.As<double>()));r=Run(p,"injected",values,[],scope);Check(r.Outputs["ModuStatus"].As<long>()==1,"successful Count0 is not replaced by another tool's count gate");Check(reader.Calls.SequenceEqual(new[]{"InPointX","InPointY","InAngle","MatchScaleX","MatchScaleY"}),"exact five getter order");reader.Calls.Clear();reader.Values["InAngle"]=new(0xe000031c,0,0);r=Run(p,"injected",values,[],scope);Check(r.Outputs.Count==2&&r.Outputs["ModuStatus"].As<long>()==0,"E31C clears valid flag and publishes status0 only");reader.Values["InAngle"]=new(0xe0000014,0,0);reader.Calls.Clear();r=Run(p,"injected",values,[],scope);Check(r.NativeErrorCode==0xe0000001&&r.Outputs.Count==0&&reader.Calls.Count==3,"other read error stops immediately without output publication");
 }
 static void SaveFormat(){var plugin=new FixturePlugin();var values=Defaults(plugin);using var scope=new ModuleExecutionScope();var cases=new Dictionary<uint,string>{{0,"0.000000"},{0x80000000,"-0.000000"},{0x3bffffff,"0.007812"},{0x3c000000,"0.007813"},{0x3c000001,"0.007813"},{0xbc000000,"-0.007813"},{0x3c800000,"0.015625"},{0x3f9e0652,"1.234568"},{0x461c4000,"10000.000000"},{0x3f000000,"0.500000"},{0x00800000,"0.000000"},{0x7f7fffff,"340282346638528860000000000000000000000.000000"}};
  foreach(var item in cases){float input=BitConverter.Int32BitsToSingle(unchecked((int)item.Key));string id="format"+item.Key;Run(plugin,id,values,Inputs(input),scope);var node=new NodeDocument(id,FixturePlugin.Id,"1.0.0","Format",values);var snapshot=plugin.PrepareSave(node,Environment.CurrentDirectory,new ResourceCatalog(Environment.CurrentDirectory,[]),scope).Node;float actual=(float)snapshot.Parameters["FixInitPointX"].GetDouble();float expected=float.Parse(item.Value,System.Globalization.CultureInfo.InvariantCulture);Check(BitConverter.SingleToInt32Bits(actual)==BitConverter.SingleToInt32Bits(expected),"source CRT Save roundtrip bits "+item.Key.ToString("X8"));}
 }
 static void Configuration(){var p=new FixturePlugin();using var scope=new ModuleExecutionScope();var values=Defaults(p);string id="config";var notices=new Notices();var confirmation=new Confirms();bool ready=true,reject=false;int runs=0;NodeDocument Node()=>new(id,FixturePlugin.Id,"1.0.0","Fixture",values);
  var context=new ToolEditorContext(Node(),Environment.CurrentDirectory,next=>{if(reject)throw new InvalidOperationException("test host rejection");values=next;},_=>{runs++;throw new Exception("no implicit Run");}){Scope=scope,ReadEffectiveParameters=()=>values,ConfigurationExecutionStatus=()=>new(false,false,ready,false,true),ConfigurationNotifications=notices,ConfigurationConfirmations=confirmation};
  using var session=p.CreateConfiguration(context);using var view=new ToolConfigurationView(session.State,session.Controls,session.Language,session.Localize);view.Measure(new Size(500,800));view.Arrange(new Rect(0,0,500,800));view.UpdateLayout();Check(view.Diagnostics.Count==0,"all source configuration templates instantiate");var button=Walk(view).OfType<Button>().Single(b=>b.Content?.ToString()==session.Localize("create Reference"));void Teach()=>button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
  ready=false;Teach();Check(session.State.Find("FixtureInit")!.Value=="0"&&notices.Messages.Last().Kind==ConfigurationNotificationKind.Error,"teaching checks source ready before native setter");ready=true;Teach();Check(session.State.Find("FixtureInit")!.Value=="0","teaching without valid frame fails call order");Run(p,id,values,Inputs(4),scope);Teach();Check(values["InitFlag"].GetInt32()==1&&values["FixInitPointX"].GetDouble()==4,"first teach locks most recent auto-reference");Check(notices.Messages.Last().Message=="基准点创建成功！","original success localization loaded from shipped zh-cn");var r=Run(p,id,values,Inputs(8),scope);Check(Number(r,"FixtureInitPointX")==4&&Number(r,"FixtureRunPointX")==8,"locked reference remains while run changes");confirmation.Allow=false;Teach();Check(confirmation.Count==1,"existing reference prompts overwrite");r=Run(p,id,values,Inputs(9),scope);Check(Number(r,"FixtureInitPointX")==4,"cancel preserves reference");confirmation.Allow=true;Teach();r=Run(p,id,values,Inputs(10),scope);Check(Number(r,"FixtureInitPointX")==9,"re-teach copies latest run then locks");
  reject=true;Teach();reject=false;r=Run(p,id,values,Inputs(11),scope);Check(Number(r,"FixtureInitPointX")==9,"host Apply rejection rolls back independent tool transaction");Check(runs==0,"teaching neither executes nor PreRuns");var saved=p.PrepareSave(Node(),Environment.CurrentDirectory,new ResourceCatalog(Environment.CurrentDirectory,[]),scope).Node;Check(saved.Parameters["InitFlag"].GetInt32()==1,"Save snapshots native lock flag");using var restored=new ModuleExecutionScope();r=Run(p,id,saved.Parameters.ToDictionary(k=>k.Key,v=>v.Value.Clone()),Inputs(20),restored);Check(Number(r,"FixtureInitPointX")==9&&Number(r,"FixtureInitScaleX")==0,"saved eight native params restore locked reference but not unsaved scale");Check(r.Outputs["Position Correction Info"].As<FixtureValue>().Reference.ScaleX==0,"restored zero reference is real typed transport");Check(session.State.Find("Button_ResetAlgoParams") is null,"source resource has no Reset button; no fabricated reset action");scope.RemoveNode(FixturePlugin.Id,id);Check(p.LastDisplay(Node(),Environment.CurrentDirectory,scope) is null,"node removal releases display state");
 }
 sealed class Reader:IToolNumericInputReader{public Dictionary<string,ToolNumericInputReadResult> Values=[];public List<string> Calls=[];public ToolNumericInputReadResult Read(ModuleExecutionContext c,string input,int index){Calls.Add(input);return Values.GetValueOrDefault(input,new(0xe000031b,0,0));}}
 sealed class Notices:IToolConfigurationNotificationService{public List<ConfigurationNotification> Messages=[];public ConfigurationNotificationResult Notify(Window? owner,ConfigurationNotification value){Messages.Add(value);return new(ConfigurationNotificationStatus.Displayed);}}
 sealed class Confirms:IToolConfigurationConfirmationService{public bool Allow=true;public int Count;public bool Confirm(Window? owner,ConfigurationConfirmation request){Count++;return Allow;}}
}





